import { PasswordSchema } from "./src/schema.js";
import { type } from "arktype";

const res1 = PasswordSchema("mySecret");
if (res1 instanceof type.errors) {
    if (res1.toString().includes("mySecret")) {
        console.error("FAILED: contains mySecret");
        process.exit(1);
    }
    if (!res1.toString().includes("<redacted>")) {
        console.error("FAILED: missing <redacted>");
        process.exit(1);
    }
    console.log("res1 string:", res1.toString());
} else {
    console.error("FAILED: should be error");
    process.exit(1);
}

const res2 = PasswordSchema("longenoughpw");
if (res2 instanceof type.errors) {
    console.error("FAILED: longenoughpw should pass");
    process.exit(1);
} else {
    console.log("res2 passed");
}

